<?php get_header(); while (have_posts()) : the_post(); ?>
<section class="page-hero page-hero--compact blog-single-hero"><div class="shell"><?php arbok_breadcrumbs(); ?><div class="blog-single-hero__grid"><div><p class="eyebrow">ARBOK blog · <?php echo esc_html(get_the_date('M j, Y')); ?></p><h1><?php the_title(); ?></h1><p class="lede"><?php echo esc_html(arbok_excerpt(34)); ?></p><div class="button-row"><a class="button" href="<?php echo esc_url(get_post_type_archive_link('update')); ?>">All blog posts</a><a class="button button-ghost" href="<?php echo esc_url(home_url('/contact/?subject=blog&post=' . rawurlencode(get_the_title()))); ?>">Contact us</a></div></div><?php if (has_post_thumbnail()) : ?><div class="blog-single-hero__media"><?php the_post_thumbnail('large', ['alt' => get_the_title()]); ?></div><?php endif; ?></div></div></section>
<section class="section blog-single-content"><article class="shell narrow prose"><?php the_content(); ?></article></section>
<section class="section section-soft"><div class="shell"><div class="section-heading"><div><p class="eyebrow dark">More from ARBOK</p><h2>Latest blog posts</h2></div><a class="text-link" href="<?php echo esc_url(get_post_type_archive_link('update')); ?>">View all posts ↗</a></div><?php $latest = new WP_Query(['post_type' => 'update', 'posts_per_page' => 3, 'post__not_in' => [get_the_ID()]]); if ($latest->have_posts()) : ?><div class="blog-grid blog-grid--compact"><?php while ($latest->have_posts()) : $latest->the_post(); ?><article class="blog-card"><a class="blog-card__media" href="<?php the_permalink(); ?>"><?php if (has_post_thumbnail()) : the_post_thumbnail('medium_large', ['alt' => get_the_title()]); else : ?><img src="<?php echo esc_url(get_template_directory_uri() . '/assets/images/arbok-logo.png'); ?>" alt="" loading="lazy"><?php endif; ?></a><div class="blog-card__body"><p class="card-meta"><?php echo esc_html(get_the_date('M j, Y')); ?></p><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(arbok_excerpt(20)); ?></p></div></article><?php endwhile; wp_reset_postdata(); ?></div><?php else : ?><p class="source-note">More blog posts will appear after publication.</p><?php endif; ?></div></section>
<?php endwhile; get_footer(); ?>
